{"tool":"write","path":"tests/test_export.py","content":""""Tests for reports.export.export_csv (RFC 4180 CSV generation)."""

import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_header_and_rows(self):
        result = export_csv(
            [{"a": 1, "b": 2}, {"a": 3, "b": 4}],
            ["a", "b"],
        )
        self.assertEqual(result, "a,b\r\n1,2\r\n3,4\r\n")

    def test_column_order_and_unselected_fields(self):
        result = export_csv(
            [{"b": 2, "a": 1, "extra": "ignored"}],
            ["a", "b"],
        )
        self.assertEqual(result, "a,b\r\n1,2\r\n")

    def test_empty_columns_header_and_blank_records(self):
        result = export_csv([{"a": 1}, {}], [])
        self.assertEqual(result, "\r\n\r\n\r\n")

    def test_empty_rows_header_only(self):
        result = export_csv([], ["a", "b"])
        self.assertEqual(result, "a,b\r\n")

    def test_missing_and_none_fields_become_empty(self):
        result = export_csv(
            [{"a": None}, {"b": 5}],
            ["a", "b"],
        )
        self.assertEqual(result, "a,b\r\n,\r\n,5\r\n")

    def test_quoting_and_doubling(self):
        result = export_csv(
            [{"a": 'say "hi"', "b": "two,words"}],
            ["a", "b"],
        )
        self.assertEqual(result, 'a,b\r\n"say ""hi""","two,words"\r\n')

    def test_embedded_newlines_preserved(self):
        result = export_csv([{"a": "x\ny", "b": "p\rq"}], ["a", "b"])
        self.assertEqual(result, 'a,b\r\n"x\ny","p\rq"\r\n')

    def test_unicode_preserved(self):
        result = export_csv([{"a": "caf\u00e9"}], ["a"])
        self.assertEqual(result, "a\r\ncaf\u00e9\r\n")

    def test_non_string_values_str(self):
        result = export_csv(
            [{"a": 1, "b": 1.5, "c": True, "d": (1, 2)}],
            ["a", "b", "c", "d"],
        )
        self.assertEqual(result, 'a,b,c,d\r\n1,1.5,True,"(1, 2)"\r\n')

    def test_one_shot_generators(self):
        result = export_csv(
            iter([{"a": 1}, {"a": 2}]),
            iter(["a"]),
        )
        self.assertEqual(result, "a\r\n1\r\n2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"1": "x"}], [1])

    def test_inputs_not_mutated(self):
        rows = [{"b": 2, "a": 1}]
        columns = ["a", "b"]
        export_csv(rows, columns)
        self.assertEqual(rows, [{"b": 2, "a": 1}])
        self.assertEqual(columns, ["a", "b"])


if __name__ == "__main__":
    unittest.main()
